compile.workshop:
variables {
    global:
        0: g
        1: h
}

//Optimize for size enabled
rule ("operands") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g >= 1;
        Global.g < 1;
        1 <= Global.g;
        Global.g > 1;
        Global.g == 1;
        Global.g != 1;
        Global.g >= Null;
        Global.g == Null;
        Add(Global.g, True) >= 1;
        Global.g == Custom String("");
        Global.g != Custom String("");
        Global.h != False;
    }
    actions {
        Set Global Variable(h, 1);
    }
}

